int main(void) {
    int A, L, N;
    scanf("%d %d", &A, &L);
    scanf("%d", &N);

    int bestId = -1;
    long long bestArea = 0;
    int found = 0;

    for (int i = 1; i <= N; i++) {
        int X, Y;
        scanf("%d %d", &X, &Y);

        if ((A <= X && L <= Y) || (A <= Y && L <= X)) {
